use std::fs::{File, TryLockError};
fn main() {
  let p = std::env::args().nth(1).unwrap();
  let f = File::options().read(true).write(true).create(true).open(&p).unwrap();
  match f.try_lock() {
    Ok(()) => println!("rust try_lock: ACQUIRED"),
    Err(TryLockError::WouldBlock) => println!("rust try_lock: WOULD-BLOCK (contended)"),
    Err(e) => println!("rust try_lock: error {e:?}"),
  }
}
EOF
